import fs from "node:fs";
import path from "node:path";
import { createRequire } from "node:module";
const root = process.argv[2];
const require = createRequire(path.join(root, "package.json"));
const compiler = require("@angular/compiler");
const files = process.argv.slice(3);
const walk = (n, cb) => { cb(n); for (const k of ["children", "inputs", "attributes", "outputs", "references"]) (n[k] || []).forEach(c => walk(c, cb)); if (n.branches) n.branches.forEach(b => walk(b, cb)); if (n.cases) n.cases.forEach(b => walk(b, cb)); if (n.blocks) n.blocks.forEach(b => walk(b, cb)); };
