  const text = fs.readFileSync(f, "utf8");
  const r = compiler.parseTemplate(text, f, { preserveWhitespaces: true });
  const out = [];
  const visit = (n) => {
    if (n instanceof compiler.Element) {
      const attrs = [...(n.attributes||[]), ...(n.inputs||[])];
      for (const a of attrs) if (a.name === "disableTooltip") out.push(`${f}:${a.sourceSpan.start.line+1} <${n.name}> ${a.constructor.name} ${a.name}`);
      n.children.forEach(visit);
    } else if (n.children) n.children.forEach(visit);
    if (n.branches) n.branches.forEach(visit);
    if (n.blocks) n.blocks.forEach(visit);
    if (n.cases) n.cases.forEach(visit);
  };
  r.nodes.forEach(visit);
  out.forEach(l => console.log(l));
}
EOF
