import fs from "node:fs";
const ng = await import("file:///C:/Users/rafal/AppData/Local/Temp/rename-bench-ng-facts-mcSnLT/node_modules/@angular/compiler/fesm2022/compiler.mjs");
const root = process.argv[2];
const files = process.argv.slice(3);
const NAME = "disableTooltip", NEW = "hideHint";
const PILL_TAGS = new Set(["app-fancy-pill", "app-status-pill", "app-pill"]);
let total = 0;
const summary = [];
for (const f of files) {
  let src = fs.readFileSync(f, "utf8");
  const edits = []; // {start,end,text}
  // A. parser-positioned attribute keys on pill tags (html files and inline templates)
  const scanTemplate = (text, base) => {
    const r = ng.parseTemplate(text, f, { preserveWhitespaces: true });
    const visit = (n) => {
      if (n && (n.inputs || n.attributes)) {
        const tag = n.name ?? n.tagName;
        if (PILL_TAGS.has(tag)) for (const a of [...(n.attributes||[]), ...(n.inputs||[])]) {
          if (a.name !== NAME) continue;
          const s = a.sourceSpan.start.offset, e = a.sourceSpan.end.offset;
          const idx = text.slice(s, e).indexOf(NAME);
          if (idx < 0) throw new Error(`no key in ${f}`);
          edits.push({ start: base + s + idx, end: base + s + idx + NAME.length, text: NEW, what: `attr <${tag}>` });
        }
      }
      for (const k of ["children","branches","blocks","cases"]) (n?.[k]||[]).forEach(visit);
    };
    r.nodes.forEach(visit);
  };
  if (f.endsWith(".html")) scanTemplate(src, 0);
  if (f.endsWith(".ts")) {
    const re = /template:\s*`([^`]*)`/g; let m;
    while ((m = re.exec(src))) scanTemplate(m[1], m.index + m[0].indexOf("`") + 1);
  }
  // B. expression reads of the input on pill-typed receivers (narrow patterns, checked by hand)
  const rx = (re, rep, what) => { let m; const r = new RegExp(re.source, "g"); while ((m = r.exec(src))) edits.push({ start: m.index + m[0].length - m[0].length + (m[0].length - m[0].replace(/^[\s\S]*?disableTooltip/, "").length) - 0, end: 0, text: "", what, _m: m }); };
  const reads = [
    [/fancyRef\.disableTooltip\(/g, "fancyRef.hideHint("],
    [/\bfancy\.disableTooltip\(/g, "fancy.hideHint("],
    [/\bpill\.disableTooltip\(/g, "pill.hideHint("],
    [/(this\.(?:fancy|firstPill)\(\)\??\.)disableTooltip\(/g, "$1hideHint("],
  ];
  for (const [re, rep] of reads) {
    for (const m of src.matchAll(re)) {
      const before = m[0].length - (m[0].length - (m[0].indexOf("disableTooltip")));
      const start = m.index + m[0].indexOf("disableTooltip");
      edits.push({ start, end: start + NAME.length, text: NEW, what: "read " + m[0] });
    }
  }
  if (f.endsWith("status-pill.component.ts") || f.endsWith("fancy-pill.component.ts")) {
    for (const m of src.matchAll(/(this\.|@if \(!|\()disableTooltip\(\)/g)) {
      const start = m.index + m[0].indexOf("disableTooltip");
      edits.push({ start, end: start + NAME.length, text: NEW, what: "inherited read" });
    }
  }
  if (f.endsWith("pill-tray.component.ts")) {
    for (const m of src.matchAll(/pill\.setInput\("disableTooltip"/g)) {
      const start = m.index + m[0].indexOf("disableTooltip");
      edits.push({ start, end: start + NAME.length, text: NEW, what: "setInput" });
    }
  }
  if (f.endsWith(".css")) {
    for (const m of src.matchAll(/app-(?:fancy-|status-)?pill\[disableTooltip\]/g)) {
      const start = m.index + m[0].indexOf("disableTooltip");
      edits.push({ start, end: start + NAME.length, text: NEW, what: "css" });
    }
  }
  if (!edits.length) continue;
  // dedupe and apply from the end
  const seen = new Set();
  const uniq = edits.filter(e => { const k = e.start; if (seen.has(k)) return false; seen.add(k); return true; });
  uniq.sort((a, b) => b.start - a.start);
  for (const e of uniq) {
    if (src.slice(e.start, e.end) !== NAME) throw new Error(`mismatch in ${f} at ${e.start}: ${src.slice(e.start, e.end)}`);
    src = src.slice(0, e.start) + e.text + src.slice(e.end);
  }
  fs.writeFileSync(f, src);
  total += uniq.length;
  summary.push(`${f}: ${uniq.length}`);
}
console.log(summary.join("\n"));
console.log("total", total);
EOF
